const base = {id:"123e4567-e89b-12d3-a456-426614174000", email:"a@b.co", name:"n", ip:"1.2.3.4", plan:"free", flags:{}};
const S = (o)=>JSON.stringify(o);
function fields(r){ if(r.ok) return "ACCEPT"; try{ return "REJECT:"+JSON.stringify(r.problems); }catch(e){ return "REJECT(?)"; } }
// --- zoned IPv6 on signup.ip
for (const ip of ["fe80::1%eth0","5ac3::de2a%wlan0","::%1","2001:db8::ff00:42:8329%25"]) {
  print("ip "+ip+" | oracle="+fields(oracle.parseSignup({...base, ip})) + " | main="+fields(main.parseSignup({...base, ip})));
}
// raw library check of zod3's .ip()
try {
  const z3 = (zod3 && zod3.z) ? zod3.z : zod3;
  print("zod3 .ip() fe80::1%eth0 -> " + z3.string().ip().safeParse("fe80::1%eth0").success);
  print("zod3 .ip() fe80::1 -> " + z3.string().ip().safeParse("fe80::1").success);
} catch(e){ print("zod3 raw error: "+e.message); }
try {
  const z4 = (zod && zod.z) ? zod.z : zod;
  print("zod4 ipv6() fe80::1%eth0 -> " + z4.ipv6().safeParse("fe80::1%eth0").success);
} catch(e){ print("zod4 raw error: "+e.message); }
// --- hosts
for (const hosts of [["2459::52d2%lo0"],["96.87.107.24","a644::8654%eth0"]]) {
  print("hosts "+S(hosts)+" | oracle="+fields(oracle.parseConfig({hosts})) + " | main="+fields(main.parseConfig({hosts})));
}
// --- timeoutMs Infinity
print("timeout Inf | oracle="+fields(oracle.parseConfig({hosts:["1.2.3.4"],timeoutMs:Infinity})) + " | main="+fields(main.parseConfig({hosts:["1.2.3.4"],timeoutMs:Infinity})));
print("timeout NaN | oracle="+fields(oracle.parseConfig({hosts:["1.2.3.4"],timeoutMs:NaN})) + " | main="+fields(main.parseConfig({hosts:["1.2.3.4"],timeoutMs:NaN})));
