// --- age
for (const age of [1e21, 9007199254740994, 1.7976931348623157e308, 30]) {
  print("age "+age+" | oracle="+fields(oracle.parseSignup({...base, age})) + " | main="+fields(main.parseSignup({...base, age})));
}
// --- website stored value
for (const website of [" https://example.com","https://example.com\n","https://example.com"]) {
  const o = oracle.parseSignup({...base, website}); const m = main.parseSignup({...base, website});
  print("website "+S(website)+" | oracle="+(o.ok?S(o.value.website):fields(o))+" | main="+(m.ok?S(m.value.website):fields(m)));
}
// --- mixed field groups
print("mix signup | oracle="+fields(oracle.parseSignup({...base, ip:"3d62::9037%1", age:1e21, email:"nope"})) + " | main="+fields(main.parseSignup({...base, ip:"3d62::9037%1", age:1e21, email:"nope"})));
print("mix config | oracle="+fields(oracle.parseConfig({hosts:["2459::52d2%lo0","zzz"], timeoutMs:Infinity})) + " | main="+fields(main.parseConfig({hosts:["2459::52d2%lo0","zzz"], timeoutMs:Infinity})));

